// foilLookupBasis.json is generated by scripts/generateFoilLookup.ts from foilSpectrum.json.
import basis from "./foilLookupBasis.json";
export type FoilSize = "board" | "detail" | "sheet";
/** Every foil style, in the order the foil shader numbers them. */
export const FOIL_STYLES = ["holo", "pink", "kyoto-seika", "gold", "silver", "roseGold"] as const;
export type FoilStyle = (typeof FOIL_STYLES)[number];
export type FoilTone = Extract<FoilStyle, "holo" | "pink" | "kyoto-seika">;
/** A color's red, green and blue channels in [0, 1]. */
export type Rgb = readonly [number, number, number];
const luminance = (c: Rgb) => 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
/** An sRGB channel in [0, 1] as linear light. */
export const srgbToLinear = (v: number) =>
  v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
const directBasis = Uint8Array.from(atob(basis.direct), (c) => c.charCodeAt(0));
const bridgeBasis = Uint8Array.from(atob(basis.bridge), (c) => c.charCodeAt(0));
type Lookup = { width: number; height: number; pixels: Uint8Array };
const lookupCache = new Map<string, Lookup>();
/** Generated spectral basis keeps admission to palette composition; pose updates reuse the texture. */
export function createFoilLookup(style: FoilStyle, palette: readonly Rgb[]): Lookup {
  if (palette.length !== 6) throw new Error("Foil requires the six authored palette colors");
  const key = JSON.stringify([style, palette]);
  const cached = lookupCache.get(key);
  if (cached) return cached;
  const { width, height } = basis,
    pixels = new Uint8Array(width * height * 4);
  const chromatic = style === "holo" || style === "pink";
  const colors = palette.map((rgb) => {
    const c: Rgb = [srgbToLinear(rgb[0]), srgbToLinear(rgb[1]), srgbToLinear(rgb[2])],
      y = luminance(c);
    if (y <= 0) throw new Error("Foil palette colors must reflect light");
    return [c[0] / y, c[1] / y, c[2] / y];
  });
  if (chromatic)
    for (let i = 0; i < width * height; i++) {
      const rgb = [0, 0, 0];
      for (let k = 0; k < 6; k++) {
        let weight = directBasis[i * 7 + k];
        if (style === "holo" && (k === 2 || k === 3)) weight -= bridgeBasis[i * 3 + k - 2];
        for (let channel = 0; channel < 3; channel++)
          rgb[channel] += Math.max(0, weight) * colors[k][channel];
      }
      if (style === "holo")
        for (let channel = 0; channel < 3; channel++) rgb[channel] += bridgeBasis[i * 3 + 2];
      const peak = Math.max(...rgb, 1e-12);
      for (let channel = 0; channel < 3; channel++)
        pixels[i * 4 + channel] = Math.round((rgb[channel] / peak) * 255);
      pixels[i * 4 + 3] = directBasis[i * 7 + 6];
    }
  const lookup = { width, height, pixels };
  lookupCache.set(key, lookup);
  return lookup;
}
/** Gaussian quadrature (Golub–Welsch) for a measure given as weights at evenly spaced coordinates. */
export function gaussQuadrature(
  coordinates: readonly number[],
  weights: readonly number[],
  count: number,
) {
  const mass = weights.reduce((sum, w) => sum + w, 0);
  let previous = coordinates.map(() => 0),
    current = coordinates.map(() => 1 / Math.sqrt(mass)),
    beta = 0;
  const matrix = Array.from({ length: count }, () => Array<number>(count).fill(0));
  for (let k = 0; k < count; k++) {
    const alpha = coordinates.reduce((sum, x, i) => sum + weights[i] * x * current[i] ** 2, 0);
    matrix[k][k] = alpha;
    const next = coordinates.map((x, i) => (x - alpha) * current[i] - beta * previous[i]);
    beta = Math.sqrt(next.reduce((sum, v, i) => sum + weights[i] * v * v, 0));
    if (k + 1 < count) matrix[k][k + 1] = matrix[k + 1][k] = beta;
    previous = current;
    current = next.map((v) => v / beta);
  }
  const eigenvectors: number[][] = Array.from({ length: count }, (_, i) =>
    Array.from({ length: count }, (_, j) => (i === j ? 1 : 0)),
  );
  for (let sweep = 0; sweep < 64; sweep++) {
    let p = 0,
      q = 0,
      largest = 0;
    for (let i = 0; i < count; i++)
      for (let j = i + 1; j < count; j++)
        if (Math.abs(matrix[i][j]) > largest) {
          largest = Math.abs(matrix[i][j]);
          p = i;
          q = j;
        }
    if (largest < 1e-14) break;
    const angle = 0.5 * Math.atan2(2 * matrix[p][q], matrix[q][q] - matrix[p][p]),
      c = Math.cos(angle),
      s = Math.sin(angle);
    for (let i = 0; i < count; i++) {
      const a = matrix[i][p],
        b = matrix[i][q];
      matrix[i][p] = c * a - s * b;
      matrix[i][q] = s * a + c * b;
      const v = eigenvectors[i][p],
        w = eigenvectors[i][q];
      eigenvectors[i][p] = c * v - s * w;
      eigenvectors[i][q] = s * v + c * w;
    }
    for (let j = 0; j < count; j++) {
      const a = matrix[p][j],
        b = matrix[q][j];
      matrix[p][j] = c * a - s * b;
      matrix[q][j] = s * a + c * b;
    }
  }
  return matrix.map((row, i) => ({ position: row[i], weight: mass * eigenvectors[0][i] ** 2 }));
}
/**
 * A level disc of light seen on the plane one unit along it: its radius across, its aspect (its
 * foreshortened height down against its width), and its logistic edge blur.
 */
export interface FoilDisc {
  readonly radius: number;
  readonly aspect: number;
  readonly feather: number;
}
/** The light's rings of samples, inner to outer, about as many as each ring's radius: sixteen. */
const DISC_RINGS = [3, 5, 8];
/**
 * roomShader's roomDisc: the light's body at q, the distance from its middle with down stretched by
 * its aspect, through a logistic blur.
 */
export const discProfile = (q: number, { radius, feather }: FoilDisc) =>
  1 / (1 + Math.exp((q - radius) / feather)) - 1 / (1 + Math.exp((q + radius) / feather));
/**
 * xyzw samples of the light in its plane's axes (x across, y down, z along the light): incident unit
 * direction and solid angle. Rings sit at the Gauss nodes of the round disc's radial measure, its
 * blurred edge and the plane's solid angle included, then are squashed down by the aspect, each
 * sample weighed by the solid angle its patch covers there; each ring's samples are evenly spaced
 * around it, turned half a step from the ring inside it so no two rings line up.
 */
export function createFoilDiscSamples(disc: FoilDisc) {
  const steps = 512,
    reach = disc.radius + 12 * disc.feather;
  const coordinates = Array.from({ length: steps }, (_, i) => ((i + 0.5) / steps) * reach);
  // A ring of radius q on the plane, seen from one unit before it: dω = 2πq·dq / (1 + q²)^(3/2).
  const weights = coordinates.map(
    (q) => (discProfile(q, disc) * 2 * Math.PI * q * (reach / steps)) / (1 + q * q) ** 1.5,
  );
  const samples = new Float32Array(64);
  let at = 0;
  gaussQuadrature(coordinates, weights, DISC_RINGS.length).forEach(({ position, weight }, ring) => {
    const count = DISC_RINGS[ring];
    for (let k = 0; k < count; k++) {
      const angle = (2 * Math.PI * (k + 0.5 * (ring % 2))) / count,
        x = position * Math.cos(angle),
        y = disc.aspect * position * Math.sin(angle),
        d = Math.hypot(x, y, 1);
      // Squashing shrinks the patch by the aspect, and moving it changes the plane's solid angle.
      const squashed = disc.aspect * ((1 + position * position) / d ** 2) ** 1.5;
      samples.set([x / d, y / d, 1 / d, (weight / count) * squashed], at);
      at += 4;
    }
  });
  return samples;
}
